import {
  DeleteObjectCommand,
  GetObjectCommand,
  HeadObjectCommand,
  ListObjectsV2Command,
  PutObjectCommand,
  S3Client,
  S3ServiceException,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

export interface PresignedUpload {
  url: string;
  method: "PUT";
  // Headers the client must send unchanged; they are part of the signature.
  headers: Record<string, string>;
}

export interface StoredObject {
  size: number;
  contentType: string | null;
}

// The operations the media service needs from object storage. Keys are
// always generated by the server.
export interface ObjectStorage {
  presignUpload(input: {
    key: string;
    contentType: string;
    contentLength: number;
    expiresInSeconds: number;
  }): Promise<PresignedUpload>;
  // Null when the object doesn't exist.
  head(key: string): Promise<StoredObject | null>;
  // The first `length` bytes, for file-signature checks.
  readStart(key: string, length: number): Promise<Uint8Array>;
  presignDownload(input: {
    key: string;
    expiresInSeconds: number;
    contentType: string;
    fileName: string | null;
  }): Promise<string>;
  // Succeeds when the object is already gone.
  delete(key: string): Promise<void>;
  // One page of keys under a prefix, for orphan reconciliation.
  list(
    prefix: string,
    cursor?: string,
  ): Promise<{ objects: { key: string; lastModified: Date }[]; cursor: string | null }>;
}

// RFC 6266 attachment header: an ASCII fallback plus the UTF-8 name.
export function contentDisposition(fileName: string | null): string {
  if (!fileName) return "attachment";
  const ascii = fileName.replace(/[^\x20-\x7e]/g, "_").replace(/["\\]/g, "_");
  return `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(fileName)}`;
}

export class S3ObjectStorage implements ObjectStorage {
  private readonly client: S3Client;

  constructor(
    private readonly bucket: string,
    region: string,
  ) {
    // Credentials come from the SDK's default provider chain. Checksums
    // only when required: a presigned PUT must not carry a checksum of an
    // empty body.
    this.client = new S3Client({
      region,
      requestChecksumCalculation: "WHEN_REQUIRED",
      responseChecksumValidation: "WHEN_REQUIRED",
    });
  }

  async presignUpload(input: {
    key: string;
    contentType: string;
    contentLength: number;
    expiresInSeconds: number;
  }): Promise<PresignedUpload> {
    // Signing Content-Length and Content-Type makes S3 itself refuse a body
    // of another size or type. No ACL: objects stay private.
    const command = new PutObjectCommand({
      Bucket: this.bucket,
      Key: input.key,
      ContentType: input.contentType,
      ContentLength: input.contentLength,
    });
    const url = await getSignedUrl(this.client, command, {
      expiresIn: input.expiresInSeconds,
      signableHeaders: new Set(["content-type", "content-length"]),
    });
    return {
      url,
      method: "PUT",
      headers: { "Content-Type": input.contentType },
    };
  }

  async head(key: string): Promise<StoredObject | null> {
    try {
      const result = await this.client.send(
        new HeadObjectCommand({ Bucket: this.bucket, Key: key }),
      );
      return { size: result.ContentLength ?? 0, contentType: result.ContentType ?? null };
    } catch (error) {
      if (isMissing(error)) return null;
      throw error;
    }
  }

  async readStart(key: string, length: number): Promise<Uint8Array> {
    const result = await this.client.send(
      new GetObjectCommand({ Bucket: this.bucket, Key: key, Range: `bytes=0-${length - 1}` }),
    );
    return result.Body ? result.Body.transformToByteArray() : new Uint8Array();
  }

  presignDownload(input: {
    key: string;
    expiresInSeconds: number;
    contentType: string;
    fileName: string | null;
  }): Promise<string> {
    // The response headers are fixed by the server: the stored type, a
    // download disposition (nothing renders inline in a browser), and a
    // private cache lifetime no longer than the URL's.
    const command = new GetObjectCommand({
      Bucket: this.bucket,
      Key: input.key,
      ResponseContentType: input.contentType,
      ResponseContentDisposition: contentDisposition(input.fileName),
      ResponseCacheControl: `private, max-age=${input.expiresInSeconds}`,
    });
    return getSignedUrl(this.client, command, { expiresIn: input.expiresInSeconds });
  }

  async delete(key: string): Promise<void> {
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }

  async list(
    prefix: string,
    cursor?: string,
  ): Promise<{ objects: { key: string; lastModified: Date }[]; cursor: string | null }> {
    const result = await this.client.send(
      new ListObjectsV2Command({ Bucket: this.bucket, Prefix: prefix, ContinuationToken: cursor }),
    );
    return {
      objects: (result.Contents ?? []).flatMap((object) =>
        object.Key ? [{ key: object.Key, lastModified: object.LastModified ?? new Date(0) }] : [],
      ),
      cursor: result.IsTruncated ? (result.NextContinuationToken ?? null) : null,
    };
  }
}

// Without s3:ListBucket, S3 answers 403 instead of 404 for a key that
// doesn't exist. The server can read every key it wrote (`pnpm
// media:check` verifies this), so for HEAD a 403 also means "not there".
function isMissing(error: unknown): boolean {
  if (!(error instanceof S3ServiceException)) return false;
  const status = error.$metadata.httpStatusCode;
  return (
    error.name === "NotFound" || error.name === "NoSuchKey" || status === 404 || status === 403
  );
}
